"""Follow-up certificate extension point.

Every active request is an obligation.  An offer may serve a request when
the service, the timing window and the offer prefix agree.  Quota forests
bound how many obligations may be served: an assignment consumes one unit
at the request group and every ancestor of that group, and one unit at the
offer group and every ancestor of that group.  The planner therefore solves a
minimum cost flow whose left side climbs the request forest and whose right
side descends the offer forest, which yields a maximum cardinality plan of
minimum total offer cost.
"""

from mcf import MinCostFlow
from protocols import probe_script


def allowed(context,offer,request):
    """Whether one offer may serve one request."""
    if offer['service']!=request['service']:
        return False
    if request['at']>offer['time']:
        return False
    lease=context['leases'][request['lease']]
    if offer['time']>=lease['end']:
        return False
    network=offer['network']
    address=request['address']
    if address<int(network.network_address) or address>int(network.broadcast_address):
        return False
    return True


def solve(context,active):
    """Return the follow-up plan of one campaign."""
    requests=context['requests']
    offers=context['offers']
    offer_quotas=context['offer_quotas']
    request_quotas=context['request_quotas']
    source=0
    sink=1
    nodes=2
    offer_forest={}
    for name in offer_quotas:
        offer_forest[name]=nodes
        nodes+=1
    offer_node={}
    for name in offers:
        offer_node[name]=nodes
        nodes+=1
    request_forest={}
    for name in request_quotas:
        request_forest[name]=nodes
        nodes+=1
    request_node={}
    for name in requests:
        if active.get(name):
            request_node[name]=nodes
            nodes+=1
    flow=MinCostFlow(nodes)
    for name,node in offer_quotas.items():
        parent=node['parent']
        if parent is None:
            flow.add_edge(source,offer_forest[name],node['capacity'],0)
        else:
            flow.add_edge(offer_forest[parent],offer_forest[name],node['capacity'],0)
    for name,offer in offers.items():
        flow.add_edge(offer_forest[offer['group']],offer_node[name],offer['capacity'],0)
    for name,request in requests.items():
        if name not in request_node:
            continue
        flow.add_edge(request_node[name],request_forest[request['group']],1,0)
    for name,node in request_quotas.items():
        parent=node['parent']
        if parent is None:
            flow.add_edge(request_forest[name],sink,node['capacity'],0)
        else:
            flow.add_edge(request_forest[name],request_forest[parent],node['capacity'],0)
    pairs=[]
    for name,offer in offers.items():
        for request_id in offer['requests']:
            if request_id not in request_node:
                continue
            request=requests[request_id]
            if not allowed(context,offer,request):
                continue
            index=flow.add_edge(offer_node[name],request_node[request_id],1,offer['cost'])
            pairs.append((index,request_id,name))
    flow.solve(source,sink)
    assignments=[]
    for index,request_id,offer_id in pairs:
        if flow.flow_on(index)>0:
            assignments.append((request_id,offer_id))
    assignments.sort()
    scripts={}
    result=[]
    total=0
    for request_id,offer_id in assignments:
        request=requests[request_id]
        kind=context['services'][request['service']]
        if kind not in scripts:
            scripts[kind]=probe_script(kind)
        send,finish=scripts[kind]
        result.append({'request':request_id,'offer':offer_id,
                       'send':list(send),'finish':list(finish)})
        total+=offers[offer_id]['cost']
    return {'resolved':len(result),'cost':total,'assignments':result}
