#!/usr/bin/env python3
"""Offline campaign entry point: targets, capture census, follow-up certificate.

The program reads one UTF-8 JSON campaign object from stdin and writes one
UTF-8 JSON result object to stdout.  Every address in the campaign is a
documentation address: nothing is contacted, no socket is opened and no
packet leaves the process.
"""
import json
import os
import sys

HERE=os.path.dirname(os.path.abspath(__file__))
for path in (HERE,os.path.join(os.path.dirname(HERE),'deps')):
    if path not in sys.path:
        sys.path.insert(0,path)

from common import CaptureError,Invalid,parse_json,validate
from gen_targets import plan
from classify_responses import capture_records
from census import build
from planning import solve

LIMIT=64*1024**2


def audit(job):
    """Run the whole offline campaign for one validated metadata object."""
    context=validate(job)
    manifest,lookup,low=plan(context['leases'],context['seed'])
    context['lookup']=lookup
    records,rejected=capture_records(context,lookup)
    snapshots,active=build(context,records,low)
    result=solve(context,active)
    return {'manifest':manifest,'rejected':rejected,'snapshots':snapshots,
            'active_requests':[{'id':name,'active':active[name]} for name in sorted(active)],
            'plan':result}


def main():
    try:
        raw=sys.stdin.buffer.read(LIMIT+1)
        if len(raw)>LIMIT:
            raise Invalid('input byte budget')
        result=audit(parse_json(raw))
    except CaptureError:
        result={'error':'capture'}
    except (Invalid,ValueError,TypeError,KeyError,IndexError,OverflowError,
            RecursionError):
        result={'error':'invalid'}
    except Exception as exc:                      # pragma: no cover - safety net
        print('campaign failure: %r'%(exc,),file=sys.stderr)
        result={'error':'invalid'}
    try:
        text=json.dumps(result,ensure_ascii=True,separators=(',',':'),allow_nan=False)
    except (ValueError,TypeError):
        text='{"error":"invalid"}'
    sys.stdout.write(text+'\n')
    sys.stdout.flush()
    return 0


if __name__=='__main__':
    sys.exit(main())
